UPDATE businesses SET description = 'Cincinnati Spur is the Spur Steak Ranches restaurant at Howard Centre in Pinelands, Cape Town, found at Shop 65 on the corner of Howard and Forest Drive. It is described as a family-friendly restaurant serving steak, ribs and burgers, and the team encourages parents to bring the kids for the well-known Spur menu and dessert. The dining directory that lists the restaurant classes its food as steakhouse and grills, with variety, vegan and vegetarian options also noted. It also takes part in the Crave dining cashback scheme, which lets eligible members earn cashback on meals eaten in, collected or delivered. Pinelands is a garden-city suburb in the Cape Town metro, and the restaurant suits families and groups looking for a relaxed sit-down grill meal.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://crave.co.za/establishment.asp?est=17543'), description_enriched_at = datetime('now') WHERE slug = 'cincinnati-spur-howard-centre-pinelands' AND description = 'Cincinnati Spur is a restaurant inside Howard Centre, Pinelands.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
