UPDATE businesses SET description = 'VDM Optometrists Kenridge is an optometry practice at The Ridge Office Park on Door de Kraal Road in Kenridge, Durbanville. The practice offers comprehensive eye examinations for adults and seniors using advanced technology, including fundus photography, and assesses the overall health of the eye rather than only updating a prescription. Through its Eyes on Diabetes initiative it uses specialised Oxia reports for the early detection and management of diabetic retinopathy. A dedicated Kids Vision service provides paediatric eye tests that go beyond school screenings, with behavioural eye testing for children who struggle with reading or tire in class. The practice also stocks a wide range of designer frames and sunglasses. It sees patients from across the Western Cape and welcomes the whole family.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.vdmoptom.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'vdm-optometrists-kenridge-kenridge' AND description = 'VDM Optometrists Kenridge is an optometry practice, in Kenridge.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
