UPDATE businesses SET description = 'Wimpy Howard Centre is a family restaurant at Shop G49 in Howard Shopping Centre on Forest Drive Service Road in Pinelands, Cape Town. The menu is built around all-day breakfasts, burgers, toasted sandwiches and thick milkshakes, along with the Famous Wimpy Grill, hearty lunches and quick coffee-and-light-meal stops. Guests can dine in, collect a takeaway or order online for delivery. The restaurant lists its trading times as 8:00 AM to 6:00 PM from Monday to Friday, 8:30 AM to 4:00 PM on Saturday and 8:30 AM to 3:00 PM on Sunday. The brand also runs a kids menu and children''s activities across its family restaurants. It is a practical stop for a weekend brunch or a casual lunch in Pinelands.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://locations.wimpy.co.za/restaurants-HowardCentre-WimpyHowardCentre'), description_enriched_at = datetime('now') WHERE slug = 'wimpy-howard-centre-pinelands' AND description = 'Wimpy is a family restaurant inside Howard Centre, Pinelands.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
