UPDATE businesses SET description = 'Bearings Distributors is a bearings and seals supplier at Maitland Industrial Park on Voortrekker Road in Maitland, Cape Town. The business serves industrial customers who cannot afford downtime, and describes sourcing as one of its strengths. If a product is not part of its standard stock or readily available in South Africa, the team will source it from anywhere in the world and quote against the customer''s required lead time. Breakdown deliveries from overseas are typically 48 to 72 hours, provided the item is off the shelf and not subject to manufacturing time. For local customers, the business states that it offers a 24-hour service, 365 days a year. Maitland is an established industrial area of Cape Town, making it a suitable base for workshops, factories and maintenance teams.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://bearingsdistributors.co.za/services/'), description_enriched_at = datetime('now') WHERE slug = 'bearings-distributors-maitland' AND description = 'Bearings Distributors is a bearings and seals supplier, in Maitland.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
