UPDATE businesses SET description = 'Blackburns Pharmacy is a community pharmacy at 153 Victoria Road in Southfield, Cape Town, and is part of the Alpha Pharmacies group. The pharmacy says it focuses on the patient rather than treating people as customers or numbers in a queue, aiming for patient-centred care that fully meets patient outcomes. It describes itself as small but offering all the pharmaceutical requirements a household needs, delivered with service with a smile. The pharmacy has been trading for more than 50 years and has seen generations of families pass through its doors, and some staff members have more than 20 years of service there. It is well known in the surrounding communities and offers AlphaScript medical aid chronic authorisation approval and follow-up for patients on ongoing medication.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.alphapharmacies.co.za/department/blackburns-pharmacy/'), description_enriched_at = datetime('now') WHERE slug = 'blackburns-pharmacy-southfield' AND description = 'Blackburns Pharmacy is a pharmacy on Victoria Road in Southfield.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
